typedef struct {
    PbnfcChartItem *items;
    size_t count;
    size_t capacity;
} PbnfcCandidateVector;

typedef struct {
    PbnfcChart *chart;
    const PbnfcGrammar *grammar;
    const PbnfcMarkupToken *tokens;
    size_t token_count;
    size_t position;
    size_t begin;
    size_t end;
    bool scanning;
    PbnfcCandidateVector candidates[PBNFC_WORKER_POOL_SIZE];
    size_t tasks[PBNFC_WORKER_POOL_SIZE];
} PbnfcParallelGeneration;

static bool candidate_reserve(PbnfcCandidateVector *vector, size_t needed)
{
    size_t capacity;
    size_t allocation_size;
    PbnfcChartItem *items;

    if (needed <= vector->capacity) {
        return true;
    }
    capacity = vector->capacity == 0U ? 8U : vector->capacity;
    while (capacity < needed) {
        if (capacity > SIZE_MAX / 2U) {
            capacity = needed;
            break;
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*items)) {
        return false;
    }
    allocation_size = capacity * sizeof(*items);
    items = (PbnfcChartItem *)realloc(vector->items, allocation_size);
    if (items == NULL) {
        return false;
    }
    vector->items = items;
    vector->capacity = capacity;
    return true;
}

static bool candidate_append(PbnfcCandidateVector *vector,
                             const PbnfcChartItem *item)
{
    if (vector->count == SIZE_MAX ||
        !candidate_reserve(vector, vector->count + 1U)) {
        return false;
    }
    vector->items[vector->count] = *item;
    ++vector->count;
    return true;
}

static void candidate_vectors_free(PbnfcCandidateVector *vectors)
{
    size_t worker_index;

    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        free(vectors[worker_index].items);
        vectors[worker_index].items = NULL;
        vectors[worker_index].count = 0U;
        vectors[worker_index].capacity = 0U;
    }
}

static void candidate_vectors_reset(PbnfcCandidateVector *vectors)
{
    size_t worker_index;

    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        vectors[worker_index].count = 0U;
    }
}

static bool parallel_prediction_candidates(PbnfcParallelGeneration *generation,
                                           size_t worker_index,
                                           const PbnfcChartItem *item,
                                           const PbnfcGrammarSymbol *symbol)
{
    size_t production;
    size_t alternative;
    PbnfcChartItem candidate;

    if (!production_index(generation->grammar, symbol->name, &production)) {
        return false;
    }
    for (alternative = 0U;
         alternative < generation->grammar->productions[production].alternative_count;
         ++alternative) {
        candidate = pbnfc_chart_item_make(production,
                                          alternative,
                                          0U,
                                          generation->position,
                                          generation->position);
        if (!candidate_append(&generation->candidates[worker_index],
                              &candidate)) {
            return false;
        }
    }
    (void)item;
    return true;
}

static bool parallel_completion_candidates(
    PbnfcParallelGeneration *generation,
    size_t worker_index,
    const PbnfcChartItem *completed)
{
    const PbnfcGrammarProduction *completed_production;
    const PbnfcChartSet *origin_set;
    size_t source_index;

    if (completed->production >= generation->grammar->production_count ||
        completed->origin >= pbnfc_chart_set_count(generation->chart)) {
        return false;
    }
    completed_production =
        &generation->grammar->productions[completed->production];
    origin_set = pbnfc_chart_set_const(generation->chart, completed->origin);
    for (source_index = 0U;
         source_index < pbnfc_chart_set_size(origin_set);
         ++source_index) {
        const PbnfcChartItem *source_item =
            pbnfc_chart_set_at(origin_set, source_index);
        const PbnfcGrammarProduction *source_production;
        const PbnfcGrammarAlternative *source_alternative;
        const PbnfcGrammarSymbol *symbol;
        PbnfcChartItem candidate;

        if (source_item == NULL ||
            source_item->production >= generation->grammar->production_count) {
            return false;
        }
        source_production =
            &generation->grammar->productions[source_item->production];
        if (source_item->alternative >= source_production->alternative_count) {
            return false;
        }
        source_alternative =
            &source_production->alternatives[source_item->alternative];
        if (source_item->dot >= source_alternative->symbol_count) {
            continue;
        }
        symbol = &source_alternative->symbols[source_item->dot];
        if (symbol->kind != PBNFC_GRAMMAR_SYMBOL_NONTERMINAL ||
            !names_equal(symbol->name, completed_production->name)) {
            continue;
        }
        candidate = pbnfc_chart_item_make(source_item->production,
                                          source_item->alternative,
                                          source_item->dot + 1U,
                                          source_item->origin,
                                          generation->position);
        if (!candidate_append(&generation->candidates[worker_index],
                              &candidate)) {
            return false;
        }
    }
    return true;
}

static bool parallel_generation_job(size_t worker_index, void *context)
{
    PbnfcParallelGeneration *generation =
        (PbnfcParallelGeneration *)context;
    const PbnfcChartSet *set =
        pbnfc_chart_set_const(generation->chart, generation->position);
    const PbnfcMarkupToken *token = NULL;
    size_t total = generation->end - generation->begin;
    size_t base = total / PBNFC_WORKER_POOL_SIZE;
    size_t remainder = total % PBNFC_WORKER_POOL_SIZE;
    size_t local_begin = generation->begin +
                         worker_index * base +
                         (worker_index < remainder ? worker_index : remainder);
    size_t local_end = local_begin + base +
                       (worker_index < remainder ? 1U : 0U);
    size_t item_index;

    if (set == NULL || local_begin > local_end || local_end > generation->end) {
        return false;
    }
    if (generation->scanning) {
        if (generation->position >= generation->token_count) {
            return false;
        }
        token = &generation->tokens[generation->position];
    }
    for (item_index = local_begin; item_index < local_end; ++item_index) {
        const PbnfcChartItem *item = pbnfc_chart_set_at(set, item_index);
        const PbnfcGrammarProduction *production;
        const PbnfcGrammarAlternative *alternative;
        const PbnfcGrammarSymbol *symbol;

        if (item == NULL || item->production >= generation->grammar->production_count) {
            return false;
        }
        production = &generation->grammar->productions[item->production];
        if (item->alternative >= production->alternative_count) {
            return false;
        }
        alternative = &production->alternatives[item->alternative];
        if (item->dot > alternative->symbol_count) {
            return false;
        }
        ++generation->tasks[worker_index];
        if (generation->scanning) {
            PbnfcChartItem candidate;

            if (item->dot == alternative->symbol_count) {
                continue;
            }
            symbol = &alternative->symbols[item->dot];
            if ((symbol->kind != PBNFC_GRAMMAR_SYMBOL_TERMINAL &&
                 symbol->kind != PBNFC_GRAMMAR_SYMBOL_TOKEN_REFERENCE) ||
                !text_matches(symbol, token)) {
                continue;
            }
            candidate = pbnfc_chart_item_make(item->production,
                                              item->alternative,
                                              item->dot + 1U,
                                              item->origin,
                                              generation->position + 1U);
            if (!candidate_append(&generation->candidates[worker_index],
                                  &candidate)) {
                return false;
            }
        } else if (item->dot == alternative->symbol_count) {
            if (!parallel_completion_candidates(generation,
                                                worker_index,
                                                item)) {
                return false;
            }
        } else {
            symbol = &alternative->symbols[item->dot];
            if (symbol->kind == PBNFC_GRAMMAR_SYMBOL_NONTERMINAL &&
                !parallel_prediction_candidates(generation,
                                                worker_index,
                                                item,
                                                symbol)) {
                return false;
            }
        }
    }
    return true;
}

static int chart_item_compare(const void *left_argument,
                              const void *right_argument)
{
    const PbnfcChartItem *left = (const PbnfcChartItem *)left_argument;
    const PbnfcChartItem *right = (const PbnfcChartItem *)right_argument;

#define PBNFC_COMPARE_FIELD(field) \
    if (left->field < right->field) { \
        return -1; \
    } \
    if (left->field > right->field) { \
        return 1; \
    }
    PBNFC_COMPARE_FIELD(production)
    PBNFC_COMPARE_FIELD(alternative)
    PBNFC_COMPARE_FIELD(dot)
    PBNFC_COMPARE_FIELD(origin)
    PBNFC_COMPARE_FIELD(position)
#undef PBNFC_COMPARE_FIELD
    return 0;
}

static bool merge_parallel_candidates(PbnfcParallelGeneration *generation)
{
    PbnfcChartItem *merged = NULL;
    size_t total = 0U;
    size_t worker_index;
    size_t item_index;
    size_t offset = 0U;

    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (total > SIZE_MAX - generation->candidates[worker_index].count) {
            return false;
        }
        total += generation->candidates[worker_index].count;
    }
    if (total != 0U) {
        if (total > SIZE_MAX / sizeof(*merged)) {
            return false;
        }
        merged = (PbnfcChartItem *)malloc(total * sizeof(*merged));
        if (merged == NULL) {
            return false;
        }
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        for (item_index = 0U;
             item_index < generation->candidates[worker_index].count;
             ++item_index) {
            merged[offset++] =
                generation->candidates[worker_index].items[item_index];
        }
    }
    if (total != 0U) {
        qsort(merged, total, sizeof(*merged), chart_item_compare);
    }
    for (item_index = 0U; item_index < total; ++item_index) {
        if (pbnfc_chart_insert(generation->chart, &merged[item_index]) ==
            PBNFC_CHART_INSERT_ERROR) {
            free(merged);
            return false;
        }
    }
    free(merged);
    return true;
}

static bool run_parallel_generation(PbnfcWorkerPool *pool,
                                    PbnfcParallelGeneration *generation,
                                    PbnfcRecognitionStats *stats)
{
    bool succeeded;
    size_t worker_index;

    candidate_vectors_reset(generation->candidates);
    succeeded = pbnfc_worker_pool_run(pool,
                                      parallel_generation_job,
                                      generation);
    if (!succeeded || !merge_parallel_candidates(generation)) {
        return false;
    }
    if (stats != NULL) {
        ++stats->rounds;
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (stats != NULL) {
            stats->tasks[worker_index] += generation->tasks[worker_index];
        }
        generation->tasks[worker_index] = 0U;
    }
    return true;
}

static bool close_parallel_position(PbnfcWorkerPool *pool,
                                    PbnfcParallelGeneration *generation,
                                    size_t position,
                                    PbnfcRecognitionStats *stats)
{
    size_t cursor = 0U;

    generation->position = position;
    generation->scanning = false;
    while (cursor < pbnfc_chart_set_size(
                        pbnfc_chart_set_const(generation->chart, position))) {
        generation->begin = cursor;
        generation->end = pbnfc_chart_set_size(
            pbnfc_chart_set_const(generation->chart, position));
        if (!run_parallel_generation(pool, generation, stats)) {
            return false;
        }
        cursor = generation->end;
    }
    return true;
}

static bool scan_parallel_position(PbnfcWorkerPool *pool,
                                   PbnfcParallelGeneration *generation,
                                   size_t position,
                                   PbnfcRecognitionStats *stats)
{
    generation->position = position;
    generation->begin = 0U;
    generation->end = pbnfc_chart_set_size(
        pbnfc_chart_set_const(generation->chart, position));
    generation->scanning = true;
    return run_parallel_generation(pool, generation, stats);
}

PbnfcRecognitionResult pbnfc_recognize_parallel(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    PbnfcRecognitionStats *stats)
{
    return pbnfc_recognize_parallel_with_diagnostics(grammar,
                                                     tokens,
                                                     token_count,
                                                     start_name,
                                                     NULL,
                                                     stats);
}

PbnfcRecognitionResult pbnfc_recognize_parallel_with_diagnostics(
    const PbnfcGrammar *grammar,
    const PbnfcMarkupToken *tokens,
    size_t token_count,
    const char *start_name,
    const PbnfcDiagnosticContext *diagnostics,
    PbnfcRecognitionStats *stats)
{
    PbnfcChart chart;
    PbnfcWorkerPool pool = {0};
    PbnfcParallelGeneration generation = {0};
    size_t start_production;
    size_t alternative;
    size_t position;
    size_t rejection_position = 0U;
    const PbnfcChartSet *rejection_set = NULL;
    const char *effective_start;
    char *expected = NULL;
    PbnfcLocation rejection_location;
    PbnfcRecognitionResult result = PBNFC_RECOGNITION_ERROR;

    if (stats != NULL) {
        (void)memset(stats, 0, sizeof(*stats));
    }
    if (grammar == NULL || (tokens == NULL && token_count != 0U) ||
        grammar->start_count == 0U) {
        return PBNFC_RECOGNITION_ERROR;
    }
    effective_start = start_name == NULL ? grammar->start_name : start_name;
    if (effective_start == NULL ||
        !production_index(grammar, effective_start, &start_production) ||
        token_count == SIZE_MAX || !pbnfc_chart_init(&chart, token_count + 1U)) {
        return PBNFC_RECOGNITION_ERROR;
    }
    if (!pbnfc_worker_pool_init(&pool)) {
        pbnfc_chart_free(&chart);
        return PBNFC_RECOGNITION_ERROR;
    }
    if (stats != NULL) {
        stats->workers = pbnfc_worker_pool_worker_count(&pool);
        stats->active_workers = stats->workers;
    }
    generation.chart = &chart;
    generation.grammar = grammar;
    generation.tokens = tokens;
    generation.token_count = token_count;
    for (alternative = 0U;
         alternative < grammar->productions[start_production].alternative_count;
         ++alternative) {
        if (!insert_item(&chart, start_production, alternative, 0U, 0U, 0U)) {
            goto cleanup;
        }
    }
    for (position = 0U; position <= token_count; ++position) {
        if (!close_parallel_position(&pool,
                                     &generation,
                                     position,
                                     stats)) {
            goto cleanup;
        }
        if (position < token_count) {
            if (!scan_parallel_position(&pool,
                                        &generation,
                                        position,
                                        stats)) {
                goto cleanup;
            }
            if (pbnfc_chart_set_size(pbnfc_chart_set_const(&chart,
                                                           position + 1U)) ==
                0U) {
                rejection_position = position;
                rejection_set = pbnfc_chart_set_const(&chart, position);
                break;
            }
        }
    }
    if (has_accepting_item(&chart,
                           grammar,
                           start_production,
                           token_count)) {
        result = PBNFC_RECOGNITION_ACCEPTED;
        goto cleanup;
    }
    if (rejection_set == NULL) {
        rejection_position = token_count;
        rejection_set = pbnfc_chart_set_const(&chart, token_count);
    }
    expected = expected_detail(rejection_set, grammar);
    if (expected == NULL) {
        goto cleanup;
    }
    rejection_location = rejection_position < token_count
                             ? tokens[rejection_position].location
                             : eof_location(tokens, token_count);
    if (diagnostics != NULL) {
        (void)pbnfc_rejection_emit(diagnostics,
                                   expected,
                                   &rejection_location);
    }
    result = PBNFC_RECOGNITION_REJECTED;

cleanup:
    free(expected);
    candidate_vectors_free(generation.candidates);
    pbnfc_worker_pool_free(&pool);
    pbnfc_chart_free(&chart);
    return result;
}
#include "grammar_ast.h"
#include "markup_lexer.h"
#include "recognizer.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int fail(const char *detail)
{
    (void)fprintf(stderr, "parallel closure smoke: %s\n", detail);
    return 1;
}

static PbnfcGrammar *parse_grammar(const char *source)
{
    PbnfcGrammar *grammar = NULL;

    if (!pbnfc_grammar_parse(source, strlen(source), NULL, &grammar) ||
        !pbnfc_grammar_validate(grammar, NULL)) {
        pbnfc_grammar_free(grammar);
        return NULL;
    }
    return grammar;
}

static bool lex_input(const char *source,
                      PbnfcMarkupToken **tokens_out,
                      size_t *count_out)
{
    PbnfcMarkupLexer lexer;
    PbnfcMarkupToken token;
    PbnfcMarkupToken *tokens = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    pbnfc_markup_lexer_init(&lexer, source, strlen(source), NULL);
    for (;;) {
        if (!pbnfc_markup_lexer_next(&lexer, &token)) {
            free(tokens);
            return false;
        }
        if (token.kind == PBNFC_MARKUP_TOKEN_EOF) {
            break;
        }
        if (count == capacity) {
            size_t next_capacity = capacity == 0U ? 16U : capacity * 2U;
            PbnfcMarkupToken *next_tokens =
                (PbnfcMarkupToken *)realloc(tokens,
                                             next_capacity * sizeof(*tokens));
            if (next_tokens == NULL) {
                free(tokens);
                return false;
            }
            tokens = next_tokens;
            capacity = next_capacity;
        }
        tokens[count] = token;
        ++count;
    }
    *tokens_out = tokens;
    *count_out = count;
    return true;
}

int main(void)
{
    static const char grammar_source[] =
        "%start Document\n"
        "%token TEXT\n"
        "Document ::= Nodes ;\n"
        "Nodes ::= Node Nodes | ;\n"
        "Node ::= Text | Group ;\n"
        "Text ::= $TEXT ;\n"
        "Group ::= '<' 'a' '>' Nodes '<' '/' 'a' '>' ;\n";
    static const char input_source[] =
        "<a>one<a>two</a>three<a>four<a>five</a></a></a>"
        "<a>six</a>seven<a>eight</a>";
    PbnfcGrammar *grammar = parse_grammar(grammar_source);
    PbnfcMarkupToken *tokens = NULL;
    size_t token_count = 0U;
    PbnfcRecognitionStats stats;
    PbnfcRecognitionResult result;
    size_t worker_index;

    if (grammar == NULL || !lex_input(input_source, &tokens, &token_count)) {
        pbnfc_grammar_free(grammar);
        free(tokens);
        return fail("parallel smoke input did not prepare");
    }
    result = pbnfc_recognize_parallel(grammar,
                                      tokens,
                                      token_count,
                                      NULL,
                                      &stats);
    if (result != PBNFC_RECOGNITION_ACCEPTED) {
        free(tokens);
        pbnfc_grammar_free(grammar);
        return fail("parallel chart did not accept nested input");
    }
    if (stats.workers != PBNFC_WORKER_POOL_SIZE ||
        stats.active_workers != PBNFC_WORKER_POOL_SIZE || stats.rounds == 0U) {
        free(tokens);
        pbnfc_grammar_free(grammar);
        return fail("parallel run did not report eight active workers");
    }
    for (worker_index = 0U;
         worker_index < PBNFC_WORKER_POOL_SIZE;
         ++worker_index) {
        if (stats.tasks[worker_index] == 0U) {
            free(tokens);
            pbnfc_grammar_free(grammar);
            return fail("a worker did not receive chart work");
        }
    }
    result = pbnfc_recognize_parallel(grammar,
                                      tokens,
                                      token_count,
                                      NULL,
                                      &stats);
    free(tokens);
    pbnfc_grammar_free(grammar);
    if (result != PBNFC_RECOGNITION_ACCEPTED || stats.rounds == 0U) {
        return fail("parallel result was not repeatable");
    }
    return 0;
}
# Project: `pbnfc`, an eight-thread BNF compiler and markup recognizer

Implement a self-contained ISO C11 command-line program that compiles a BNF
grammar and recognizes hierarchical HTML-like documents. The recognizer must
perform its parsing work through a persistent pool of exactly eight POSIX worker
threads and deterministically combine their partial results. External parser
generators and non-standard libraries are forbidden; POSIX `pthread` is allowed.

This is not a file-splitting exercise. All eight workers cooperate on the chart
for one document. A coordinator distributes chart items in parallel rounds,
workers produce thread-local candidates, and the coordinator merges and
deduplicates those candidates in a stable order before the next round.

## Required interface

`make clean all` must build `bin/pbnfc` with strict warnings and pthread support.

```text
bin/pbnfc --grammar PATH --input PATH [--start NAME] [--stats]
```

On recognition success, exit 0 and print:

```text
ACCEPT tokens=N
```

With `--stats`, append these fields on the same line:

```text
workers=8 active_workers=8 rounds=N tasks=N,N,N,N,N,N,N,N
```

Every task count must be positive for the supplied stress document. `rounds`
must be positive. Without `--stats`, output must be deterministic and contain
no timing or scheduling-dependent values.

For a syntactically valid grammar with rejected markup, exit 1 and print one
line beginning `REJECT ` with decimal byte `offset=`, `line=`, and `column=`
fields plus a nonempty `expected=` field. For command-line, markup-lexing,
grammar-lexing, grammar-parsing, undefined-symbol, or left-recursion errors,
exit 2 and print one line beginning `GRAMMAR_ERROR ` with useful detail.

## Grammar language

Whitespace is insignificant and `#` begins a comment through end of line. The
first directive is `%start NAME`. Zero or more token-kind declarations follow:

```text
%token IDENT
%token STRING
%token TEXT
```

Productions use `::=`, `|`, and `;`:

```text
Name ::= symbol symbol | another-alternative | ;
```

An empty alternative denotes epsilon. A single-quoted terminal matches an exact
markup token lexeme. Support `\\'` and `\\\\` escapes inside grammar terminals.
`$IDENT`, `$STRING`, and `$TEXT` match the declared markup token kind regardless
of lexeme. Bare identifiers are nonterminal references. Each rule name is
defined once and every nonterminal and `$TOKEN` reference must be defined.

Detect direct and indirect left recursion before recognition. Right recursion,
epsilon, nested expansion, and ambiguous alternatives must terminate safely.
The engine must consume the entire markup token stream to accept. Do not
hard-code the acceptance examples or tag hierarchy in C; they come from the
compiled grammar.

## Built-in markup lexer

Tokenize compact markup without requiring whitespace between punctuation:

- Inside `<...>`, recognize `<`, `>`, `/`, and `=` as exact literal lexemes.
- Recognize identifiers using `[A-Za-z_:][A-Za-z0-9_.:-]*`; their kind is
  `IDENT`, while exact terminals such as `'a'` may also match their lexeme.
- Recognize both single- and double-quoted attribute values as kind `STRING`,
  with backslash escapes for a quote and backslash.
- Outside tags, each nonempty maximal text run is one `TEXT` token. Preserve its
  byte location while ignoring runs that contain only ASCII whitespace.
- Reject unterminated tags, quoted values, and invalid bytes with accurate
  byte, line, and column diagnostics.

The required grammar must be able to recognize compact nested markup such as:

```html
<a href='url'> link text </a>
<div id="root"><p>Hello <strong>world</strong></p><img src='x.png'/></div>
```

Opening and closing tags must match because the grammar defines separate rules
for `a`, `div`, `span`, `p`, `section`, `ul`, `li`, `strong`, and `em`; `img`
is self-closing. Attributes may appear on every tag and use the recursive
attribute productions. Mismatched, unknown, or malformed tags must reject.

## Required eight-thread parser architecture

Use a safe general chart recognizer, such as Earley recognition. Create exactly
eight worker pthreads once per process and reuse them until parsing ends.

For each chart position and fixed-point closure wave:

1. The coordinator snapshots the current unprocessed item range and partitions
   it across all eight workers.
2. Workers perform prediction/completion work and write only to their own
   candidate vectors; shared grammar and chart snapshots are read-only.
3. A barrier or condition-variable generation protocol returns control to the
   coordinator.
4. The coordinator stable-sorts or otherwise deterministically orders all
   candidates, merges duplicates, appends new items, and repeats until closure.
5. Scanning work is likewise distributed through the pool, with next-position
   candidates combined deterministically.

All workers must perform real chart work on the stress case. Protect lifecycle
state with mutexes/condition variables or barriers, handle allocation failures,
join all threads on every normal/error exit, and avoid data races. Do not create
a new set of threads for every token or chart item. The coordinator is not one
of the eight reported workers.

## Required engineering properties

- Compile C with `-std=c11 -Wall -Wextra -Werror -pedantic -pthread`.
- Keep implementation under `src/` and headers under `include/`.
- Separate grammar lexer/parser, markup lexer, chart representation, worker
  pool, recognizer, diagnostics, and CLI into understandable modules.
- Add `make test` with focused grammar, markup, rejection, and concurrency tests.
- Avoid global mutable parser state and free allocated memory on normal exits.
- Document grammar syntax, markup tokenization, parallel merge invariants,
  limitations, examples, output, and exit statuses in `README.md`.

## Required manager work breakdown

Keep these ten plan items distinct and independently verifiable. Additional
repair items are allowed only after an item fails its acceptance check.

1. Strict pthread build skeleton, CLI contract, locations, and diagnostics.
2. BNF lexer with directives, token kinds, escapes, alternatives, and epsilon.
3. Grammar AST, ownership-safe storage, symbol resolution, and validation.
4. Markup lexer for compact tags, text, identifiers, and quoted attributes.
5. Sequential chart/item semantics serving as a correctness baseline.
6. Persistent eight-thread pool, generation protocol, and clean shutdown.
7. Parallel prediction/completion rounds with thread-local candidate buffers.
8. Parallel scanning, deterministic merge/deduplication, and worker statistics.
9. Hierarchical HTML grammar integration, rejection diagnostics, and stress cases.
10. Strict full build, regression suite, concurrency checks, README, and final validation.

## Acceptance grammar

The implementation and external grader use this grammar shape (additional
equivalent factoring is allowed in the project's own tests):

```text
%start Document
%token IDENT
%token STRING
%token TEXT
Document ::= Nodes ;
Nodes ::= Node Nodes | ;
Node ::= Text | A | Div | Span | P | Section | Ul | Li | Strong | Em | Img ;
Text ::= $TEXT ;
Attributes ::= Attribute Attributes | ;
Attribute ::= $IDENT '=' $STRING ;
A ::= '<' 'a' Attributes '>' Nodes '<' '/' 'a' '>' ;
Div ::= '<' 'div' Attributes '>' Nodes '<' '/' 'div' '>' ;
Span ::= '<' 'span' Attributes '>' Nodes '<' '/' 'span' '>' ;
P ::= '<' 'p' Attributes '>' Nodes '<' '/' 'p' '>' ;
Section ::= '<' 'section' Attributes '>' Nodes '<' '/' 'section' '>' ;
Ul ::= '<' 'ul' Attributes '>' Nodes '<' '/' 'ul' '>' ;
Li ::= '<' 'li' Attributes '>' Nodes '<' '/' 'li' '>' ;
Strong ::= '<' 'strong' Attributes '>' Nodes '<' '/' 'strong' '>' ;
Em ::= '<' 'em' Attributes '>' Nodes '<' '/' 'em' '>' ;
Img ::= '<' 'img' Attributes '/' '>' ;
```
